package com.yazoni.client.ui;
import com.yazoni.client.module.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class YazoniSettingsScreen extends Screen{private final Module module;private int scroll;public YazoniSettingsScreen(Module m){super(Component.literal(m.name()+" Settings"));module=m;}
@Override public void render(GuiGraphics g,int mx,int my,float d){super.render(g,mx,my,d);g.fill(0,0,width,height,0xE8080A0D);int l=Math.max(20,width/2-250),t=Math.max(20,height/2-190);g.fill(l,t,l+500,t+380,0xF012161C);g.fill(l,t,l+500,t+3,0xFFFF6900);g.drawString(font,module.name(),l+18,t+18,0xFFFFFFFF,true);g.drawString(font,module.enabled()?"ENABLED":"DISABLED",l+390,t+18,module.enabled()?0xFF55DD88:0xFF9AA1AA,true);int y=t+55-scroll;for(Setting<?> s:module.settings()){boolean h=mx>=l+15&&mx<=l+485&&my>=y&&my<=y+42;g.fill(l+15,y,l+485,y+42,h?0xFF202831:0xFF181D24);g.drawString(font,s.name(),l+28,y+8,0xFFFFFFFF);g.drawString(font,value(s),l+28,y+24,0xFFFF9B4A);y+=49;}g.drawString(font,"Click to change • Scroll • ESC to close",l+18,t+355,0xFF68727E);}
private String value(Setting<?> s){if(s instanceof BooleanSetting b)return b.value()?"ON":"OFF";if(s instanceof NumberSetting n){double v=n.value();return v==Math.rint(v)?Integer.toString((int)v):String.format(java.util.Locale.ROOT,"%.1f",v);}if(s instanceof EnumSetting<?> e)return e.value().name();return String.valueOf(s.value());}
@Override public boolean mouseClicked(double mx,double my,int button){if(button!=0)return super.mouseClicked(mx,my,button);int l=Math.max(20,width/2-250),t=Math.max(20,height/2-190),y=t+55-scroll;for(Setting<?> s:module.settings()){if(mx>=l+15&&mx<=l+485&&my>=y&&my<=y+42){if(s instanceof BooleanSetting b)b.toggle();else if(s instanceof NumberSetting n){double v=n.value()+n.step();if(v>n.max())v=n.min();n.value(v);}else if(s instanceof EnumSetting<?> e)cycle(e);return true;}y+=49;}return super.mouseClicked(mx,my,button);}
@SuppressWarnings({"rawtypes","unchecked"})private void cycle(EnumSetting<?> s){Enum cur=(Enum)s.value();Enum[] v=s.values();((Setting)s).value(v[(cur.ordinal()+1)%v.length]);}
@Override public boolean mouseScrolled(double mx,double my,double sx,double sy){scroll-=(int)(sy*30);int max=Math.max(0,module.settings().size()*49-300);scroll=Math.max(0,Math.min(max,scroll));return true;}}
